<section><h1>Roles</h1><p>The five system roles are fixed. Manage their permission assignments instead.</p><div class="table-wrap"><table><thead><tr><th>Role</th><th>Users</th><th>Permissions</th><th></th></tr></thead><tbody><?php foreach (($result['items'] ?? array()) as $role): ?><tr><td><?= dts_escape($role['role_name']) ?></td><td><?= dts_escape($role['user_count']) ?></td><td><?= dts_escape($role['permission_count']) ?></td><td><a href="<?= dts_escape(site_url('roles/view/'.$role['role_id'])) ?>">View</a></td></tr><?php endforeach; ?></tbody></table></div></section>
